# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_ip_address() {
    ip -o addr show 2>/dev/null | gawk 'NF >= 4 { sub(/\/.*/, "", $4); print $4 }'
}

_choice_ip_args() {
    local cmd="${argc__cmd_fn:-}"
    cmd="${cmd%_}"
    case "$cmd" in
    route::add|route::append|route::change|route::replace|route::del)
        cat <<-'EOF' | _argc_util_comp_tv
	to=`_choice_ip_address`;;destination prefix
	dev=`_choice_ip_device`;;output device
	via=`_choice_ip_address`;;gateway address
	src=`_choice_ip_address`;;preferred source address
	table=`_choice_ip_table`;;routing table
	proto=`_choice_ip_proto`;;routing protocol
	scope=`_choice_ip_scope`;;address scope
	metric=;;route preference
	mtu=;;MTU
	vrf=`_choice_ip_vrf`;;VRF name
	onlink;;pretend nexthop is directly attached
	nexthop=;;nexthop specification
	encap=;;encapsulation type
	EOF
        ;;
    route::show|route::flush|route::get|route::save)
        cat <<-'EOF' | _argc_util_comp_tv
	to=`_choice_ip_address`;;destination prefix
	from=`_choice_ip_address`;;source prefix
	dev=`_choice_ip_device`;;output device
	iif=`_choice_ip_device`;;input device
	oif=`_choice_ip_device`;;output device
	table=`_choice_ip_table`;;routing table
	proto=`_choice_ip_proto`;;routing protocol
	scope=`_choice_ip_scope`;;address scope
	type=`_choice_ip_link_type`;;link type
	vrf=`_choice_ip_vrf`;;VRF name
	mark=;;fwmark
	tos=;;TOS
	metric=;;route preference
	root;;match the root of a prefix
	match;;match an exact prefix
	exact;;match an exact prefix
	cached;;dump cached routes
	connected;;only connected routes
	fibmatch;;fibmatch
	EOF
        ;;
    address::add|address::change|address::replace|address::delete)
        cat <<-'EOF' | _argc_util_comp_tv
	dev=`_choice_ip_device`;;device name
	local=`_choice_ip_address`;;local address
	peer=`_choice_ip_address`;;peer address
	broadcast=`_choice_ip_address`;;broadcast address
	anycast=`_choice_ip_address`;;anycast address
	label=;;address label
	scope=`_choice_ip_scope`;;address scope
	proto=`_choice_ip_proto`;;address protocol
	valid_lft=;;valid lifetime
	preferred_lft=;;preferred lifetime
	home;;home address
	mngtmpaddr;;manage temporary addresses
	nodad;;skip duplicate address detection
	optimistic;;optimistic duplicate address detection
	noprefixroute;;do not create a prefix route
	autojoin;;autojoin multicast groups
	EOF
        ;;
    address::show|address::flush|address::save)
        cat <<-'EOF' | _argc_util_comp_tv
	dev=`_choice_ip_device`;;device name
	scope=`_choice_ip_scope`;;address scope
	to=`_choice_ip_address`;;only addresses matching the prefix
	label=;;address label pattern
	master=`_choice_ip_device`;;master device
	vrf=`_choice_ip_vrf`;;VRF name
	type=`_choice_ip_link_type`;;link type
	proto=`_choice_ip_proto`;;address protocol
	up;;only running interfaces
	down;;only stopped interfaces
	nomaster;;only interfaces without a master
	permanent;;permanent addresses
	dynamic;;dynamically assigned addresses
	secondary;;secondary addresses
	primary;;primary addresses
	tentative;;tentative addresses
	deprecated;;deprecated addresses
	dadfailed;;addresses that failed duplicate address detection
	temporary;;temporary addresses
	EOF
        ;;
    link::add)
