_choice_ip_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_ip_device() {
    ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
}

_choice_ip_exec_command() {
    if [[ "${#argc__positionals[@]}" -le 2 ]]; then
        _choice_ip_command
    else
        _argc_util_comp_subcommand 1
    fi
}

_choice_ip_family() {
    cat <<-'EOF'
	inet	IPv4 family
	inet6	IPv6 family
	bridge	bridge family
	mpls	MPLS family
	link	no protocol family
	EOF
}

_choice_ip_link_type() {
    ip link help 2>&1 | gawk '
        /^TYPE :=/ { collecting = 1 }
        collecting {
            text = $0
            if (index(text, "{") > 0) {
                sub(/^[^{]*[{][ \t]*/, "", text)
            } else {
                sub(/^[ \t]+/, "", text)
            }
            if (index(text, "}") > 0) {
                sub(/[ \t]*[}].*$/, "", text)
                collecting = 0
            }
            count = split(text, items, "|")
            for (i = 1; i <= count; i++) {
                gsub(/^[ \t]+|[ \t]+$/, "", items[i])
                if (items[i] != "") print items[i]
            }
        }'
}

_choice_ip_netns() {
    ip netns list 2>/dev/null | gawk '{ print $1 }'
}

_choice_ip_netns_command() {
    _choice_ip_netns
    _argc_util_comp_command
}

_choice_ip_on_off() {
    printf '%s\n' on off
}

_choice_ip_proto() {
    if [[ -r /etc/iproute2/rt_protos ]]; then
        gawk '$1 !~ /^#/ && NF >= 2 { print $2 }' /etc/iproute2/rt_protos
    else
        printf '%s\n' kernel boot static ra dhcp xfrm redirect gated mrt zebra bird unspec
    fi
}

_choice_ip_scope() {
    if [[ -r /etc/iproute2/rt_scopes ]]; then
        gawk '$1 !~ /^#/ && NF >= 2 { print $2 }' /etc/iproute2/rt_scopes
    else
        printf '%s\n' global site link host nowhere
    fi
}

_choice_ip_table() {
    if [[ -r /etc/iproute2/rt_tables ]]; then
        gawk '$1 !~ /^#/ && NF >= 2 { print $2 }' /etc/iproute2/rt_tables
    fi
    printf '%s\n' local main default all
}

_choice_ip_tun_mode() {
    printf '%s\n' tun tap
}

_choice_ip_vrf() {
    ip -o link show type vrf 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
}

_choice_ip_vrf_command() {
    _choice_ip_vrf
    _argc_util_comp_command
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
